// Module A: z = (x ^ y) & x
module A (
    input  wire x,
    input  wire y,
    output wire z
);
    assign z = (x ^ y) & x;
endmodule

// Module B: from the waveform, z = 1 for (0,0) and (1,1), so z = ~(x ^ y)
module B (
    input  wire x,
    input  wire y,
    output wire z
);
    assign z = ~(x ^ y);
endmodule

// Top-level module
module top (
    input  wire x,
    input  wire y,
    output wire z
);
    wire a1, a2;
    wire b1, b2;
    wire or_out, and_out;

    // First A and B submodules
    A u_a1 (
        .x(x),
        .y(y),
        .z(a1)
    );

    B u_b1 (
        .x(x),
        .y(y),
        .z(b1)
    );

    // Second A and B submodules
    A u_a2 (
        .x(x),
        .y(y),
        .z(a2)
    );

    B u_b2 (
        .x(x),
        .y(y),
        .z(b2)
    );

    // First pair goes to OR
    or u_or (
        .out(or_out),
        .in1(a1),
        .in2(b1)
    );

    // Second pair goes to AND
    and u_and (
        .out(and_out),
        .in1(a2),
        .in2(b2)
    );

    // OR and AND outputs go to XOR
    xor u_xor (
        .out(z),
        .in1(or_out),
        .in2(and_out)
    );
endmodule
```

